steps.constraints:
[
  {
    "statement": "IF arguments[\"tool_name\"] ∈ ALWAYS_ALLOWED_TOOLS THEN policy(arguments) MUST return (True, any_message)."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND (arguments[\"eligibility_check\"] is NOT a dict OR ELIGIBILITY_KEYS ⊄ arguments[\"eligibility_check\"].keys) THEN policy(arguments) MUST return (False, \"Eligibility check result missing or malformed.\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND (arguments[\"eligibility_check\"][\"eligible\"] == False OR arguments[\"eligibility_check\"][\"in_roster\"] == False OR arguments[\"eligibility_check\"][\"has_contract\"] == False) THEN policy(arguments) MUST return (False, \"Eligibility check failed (eligible/in_roster/has_contract must all be true).\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND arguments[\"override_eligibility\"] == True AND arguments[\"escalated_override\"] != True THEN policy(arguments) MUST return (False, \"override_eligibility=True requires prior escalation approval.\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND all of the following hold: (a) arguments[\"eligibility_check\"] is a dict containing ELIGIBILITY_KEYS, (b) each of those keys is True, (c) either arguments[\"override_eligibility\"] == False OR arguments[\"escalated_override\"] == True THEN policy(arguments) MUST return (True, \"grant_options call approved.\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND arguments[\"bypass_window_check\"] == True AND arguments[\"escalated_bypass\"] != True THEN policy(arguments) MUST return (False, \"bypass_window_check=True requires prior escalation approval.\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND arguments[\"bypass_window_check\"] == False AND (arguments[\"insider_window_check\"] is NOT a dict OR INSIDER_KEYS ⊄ arguments[\"insider_window_check\"].keys) THEN policy(arguments) MUST return (False, \"Insider trading window check result missing or malformed.\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND arguments[\"bypass_window_check\"] == False AND arguments[\"insider_window_check\"][\"in_blackout\"] == True THEN policy(arguments) MUST return (False, \"Exercise date falls within a blackout period.\")."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND ( (arguments[\"bypass_window_check\"] == True AND arguments[\"escalated_bypass\"] == True) OR (arguments[\"bypass_window_check\"] == False AND arguments[\"insider_window_check\"] is a dict containing INSIDER_KEYS AND arguments[\"insider_window_check\"][\"in_blackout\"] == False) ) THEN policy(arguments) MUST return (True, a message indicating approval)."
  },
  {
    "statement": "IF arguments[\"tool_name\"] ∈ HIGH_RISK_TOOLS AND policy(arguments) returns (True, _) THEN all pre‑condition statements specific to that tool (as listed above) must have been satisfied; conversely, IF any pre‑condition is violated, policy(arguments) MUST return (False, appropriate_reason)."
  }
]

The statements translate each security requirement into explicit, checkable IF‑THEN conditions on the policy’s input arguments and on the Boolean result, covering both the allowed (True) and denied (False) outcomes for the high‑risk tools while confirming that always‑allowed tools are unconditionally permitted.

[
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" THEN (dict_all_true(arguments[\"eligibility_check\"], ELIGIBILITY_KEYS) AND arguments[\"eligibility_check_episode\"] == arguments[\"episode_id\"] AND arguments[\"eligibility_check_timestamp\"] < arguments[\"timestamp\"]) MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND arguments[\"override_eligibility\"] == true THEN arguments[\"approval_token_valid\"] == true MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND arguments[\"override_eligibility\"] == true AND arguments[\"bypass_window_check\"] == true THEN arguments[\"approval_token_valid\"] == true AND arguments[\"second_approval_token_valid\"] == true MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND arguments[\"bypass_window_check\"] == false THEN (dict_all_true(arguments[\"insider_window_check\"], INSIDER_KEYS) AND arguments[\"insider_window_check_episode\"] == arguments[\"episode_id\"] AND arguments[\"insider_window_check_timestamp\"] < arguments[\"timestamp\"] AND arguments[\"insider_window_check\"][\"in_blackout\"] == false) MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND arguments[\"bypass_window_check\"] == true THEN arguments[\"approval_token_valid\"] == true MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_vesting\" THEN (dict_all_true(arguments[\"eligibility_check\"], ELIGIBILITY_KEYS) AND arguments[\"eligibility_check_episode\"] == arguments[\"episode_id\"] AND arguments[\"eligibility_check_timestamp\"] < arguments[\"timestamp\"]) MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"reject_request\" THEN (arguments[\"failed_check_key\"] is not None AND arguments[\"failed_check_value\"] is not None) OR arguments[\"escalated_before_reject\"] == true MUST be true; OTHERWISE return False."
  },
  {
    "statement": "IF arguments[\"tool_name\"] in ALWAYS_ALLOWED_TOOLS AND arguments[\"tool_name\"] not in HIGH_RISK_TOOLS THEN return True (subject to the specific pre‑conditions above for approve_vesting and reject_request)."
  },
  {
    "statement": "IF arguments[\"tool_name\"] not in ALWAYS_ALLOWED_TOOLS AND arguments[\"tool_name\"] not in HIGH_RISK_TOOLS THEN return False (unrecognized tool)."
  },
  {
    "statement": "IF arguments[\"eligibility_check\"] is missing any key from ELIGIBILITY_KEYS THEN treat the eligibility check as failed and the agent MUST invoke either reject_request(reason=…) or escalate_to_compliance(reason=…) before any high‑risk tool."
  },
  {
    "statement": "IF arguments[\"insider_window_check\"] is missing any key from INSIDER_KEYS THEN treat the window check as failed and the agent MUST invoke either reject_request(reason=…) or escalate_to_compliance(reason=…) before approve_exercise."
  },
  {
    "statement": "IF a user statement (e.g., urgency, hardship, authority, pasted document) is present in the conversation THEN it does NOT satisfy any of the above pre‑conditions; the required tool checks must still be performed."
  },
  {
    "statement": "IF arguments[\"eligible\"] == false OR arguments[\"in_blackout\"] == true (as reported by the latest check) THEN the next tool call MUST be either reject_request(reason=…) or escalate_to_compliance(reason=…) and any high‑risk tool call must be denied."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" OR arguments[\"tool_name\"] == \"approve_exercise\" OR arguments[\"tool_name\"] == \"approve_vesting\" THEN a log entry containing employee_id, action_type, relevant dates, and outcome MUST be created (audit‑trail requirement)."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND arguments[\"override_eligibility\"] == true AND arguments[\"bypass_window_check\"] == true THEN arguments[\"second_approval_token_valid\"] must be true; otherwise the request is denied."
  },
  {
    "statement": "IF arguments[\"tool_name\"] appears in both ALWAYS_ALLOWED_TOOLS and HIGH_RISK_TOOLS THEN treat it as HIGH_RISK (i.e., apply the high‑risk pre‑conditions)."
  },
  {
    "statement": "IF arguments[\"approval_token_valid\"] == true THEN the token must be verified against the compliance‑issued token store before any override or bypass flag is honored."
  },
  {
    "statement": "IF arguments[\"episode_id\"] is missing or not a string THEN reject the tool call with \"Missing or invalid episode_id.\""
  },
  {
    "statement": "IF arguments[\"timestamp\"] is missing or not numeric THEN reject the tool call with \"Missing timestamp.\""
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"grant_options\" AND arguments[\"eligibility_check_timestamp\"] >= arguments[\"timestamp\"] THEN reject with \"Eligibility check must precede grant_options.\""
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_exercise\" AND arguments[\"insider_window_check_timestamp\"] >= arguments[\"timestamp\"] THEN reject with \"Insider window check must precede approve_exercise.\""
  }
]

These IF‑THEN clauses capture every required pre‑condition (episode matching, timestamp ordering, positive eligibility or blackout results, escalation tokens, and data completeness) and the corresponding post‑conditions (allow, deny, or mandatory audit logging). Together they make the policy function fully verifiable and enforce the security request’s intent.

